import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.NpvCl_7q.js";const u=JSON.parse('{"title":"Linux","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/linux.md","filePath":"platforms/linux.md","lastUpdated":1794122820000}'),s={name:"platforms/linux.md"};function n(r,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h1><p>MasonKit supports Linux through the NativeScript Linux runtime (<code>@nativescript/linux</code>), which draws with GTK 4. The same TypeScript API, elements and CSS work there; the native side is a Rust library over GTK instead of a Swift framework or an Android library.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Add the Linux platform to your app and install the plugin as usual:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @triniwiz/nativescript-masonkit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ns</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux</span></span></code></pre></div><p>The plugin declares <code>linux: 0.1.0-alpha.0</code> as its minimum runtime. The Linux runtime is in alpha. Apps need GTK 4.6 or later at run time.</p><p>Nothing else is required. The package ships <code>libmasonkit.so</code> for x64 and arm64 (<code>platforms/linux/lib/x64</code>, <code>platforms/linux/lib/arm64</code>) and its C header <code>platforms/linux/include/mason_linux.h</code>. When your app builds, the CLI copies the library next to the app and runs the metadata generator over the header, so the library&#39;s functions are callable from JavaScript.</p><p>Fonts in your app&#39;s <code>fonts</code> folder are registered with fontconfig at startup, so a custom <code>font-family</code> resolves by name. Fonts loaded at run time (<code>@font-face</code>, <code>FontFace</code>) go through <code>@nativescript/font-manager</code>: <code>libmasonkit.so</code> links its <code>libfontmanager.so</code>, resolves families through it, and lays text out again when a face loads.</p><h2 id="what-the-library-contains" tabindex="-1">What the library contains <a class="header-anchor" href="#what-the-library-contains" aria-label="Permalink to &quot;What the library contains&quot;">​</a></h2><p><code>libmasonkit.so</code> (crate <code>crates/mason-linux</code>) wraps the same Rust engine as the other platforms and adds one GTK widget, <code>MasonElement</code>, behind every element:</p><ul><li>A container mirrors its Mason node&#39;s children to its GTK children. The topmost element computes the tree and every element places its children from that layout.</li><li>Text, nested inline text and inline boxes form one Pango paragraph, which is the text node&#39;s measure. Inline boxes stay GTK widgets, placed where their object replacement character lands.</li><li>Backgrounds, gradients, borders, box shadows and filters are drawn with GSK render nodes.</li><li><code>&lt;input&gt;</code> and <code>&lt;textarea&gt;</code> host a GTK control (an entry, a check button, a scale, a color button or a text view) in their content box.</li></ul><p>In TypeScript, <code>native.linux.ts</code> exposes the library as <code>NativeScript.Mason</code> (<code>View</code>, <code>Text</code>, <code>Css</code>, ...). Each element object is also the <code>GtkWidget</code> pointer, so core treats it like any other native view. CSS is parsed in TypeScript.</p><p>Plain NativeScript views inside a Mason element are measured and laid out through core, at the size and position Mason gives them.</p><h2 id="differences-from-the-other-platforms" tabindex="-1">Differences from the other platforms <a class="header-anchor" href="#differences-from-the-other-platforms" aria-label="Permalink to &quot;Differences from the other platforms&quot;">​</a></h2><ul><li><strong>Masks and <code>clip-path</code>.</strong> A <code>clip-path</code> that is a box, <code>inset()</code>, <code>circle()</code> or <code>ellipse()</code> is a GPU clip. Polygons, paths, <code>mask-image</code> layers and <code>mask-border</code> use a mask: GTK 4.10 and later draw it on the GPU, GTK 4.6 to 4.8 composite the element in software, which costs more for large masked elements. Taps outside a <code>clip-path</code> go to whatever is underneath.</li><li><strong><code>backdrop-filter</code></strong> filters the Mason content behind the element, from its layout root down. Plain GTK or NativeScript views behind that root aren&#39;t part of the backdrop.</li><li><strong>Scrolling.</strong> <code>overflow: scroll</code> and <code>auto</code> scroll with the wheel, touchpad (with momentum) and touch drag, and show overlay indicators while moving. <code>&lt;scroll&gt;</code> wraps its content in a <code>GtkScrolledWindow</code> instead.</li><li><strong>Vertical writing modes</strong> draw with Pango&#39;s vertical gravity. <code>text-orientation: upright</code> keeps CJK upright but turns other scripts sideways, as <code>mixed</code> does.</li><li><strong>Not yet on Linux:</strong> <code>position: fixed</code> and <code>sticky</code> scroll with the content instead of staying in place, <code>text-combine-upright</code> and <code>text-spacing-trim</code> are ignored, and text in a vertical box doesn&#39;t wrap around floats.</li><li><strong>Remote images</strong> are fetched with the runtime&#39;s <code>fetch</code>; files and <code>data:</code> URIs load directly.</li></ul><p>See the <a href="/nativescript-mason/platforms/">support matrix</a> for features that differ across all platforms.</p><h2 id="building-the-library" tabindex="-1">Building the library <a class="header-anchor" href="#building-the-library" aria-label="Permalink to &quot;Building the library&quot;">​</a></h2><p>The prebuilt library ships in the npm package. To rebuild it you need Rust and the GTK 4 development files (<code>libgtk-4-dev</code> 4.6 or later):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:linux</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # from packages/nativescript-masonkit</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tools/scripts/masonkit-build-linux.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--debug]</span></span></code></pre></div><p>The script builds <code>crates/mason-linux</code> and copies <code>libmasonkit.so</code> and <code>mason_linux.h</code> into <code>packages/nativescript-masonkit/platforms/linux</code>. Without the development package, point <code>NS_SYSROOT</code> at a sysroot made by the Linux runtime&#39;s <code>metadata-generator/linux/fetch-sysroot.sh</code>: the script takes the headers and <code>.pc</code> files from there and links against the system&#39;s GTK libraries.</p><p>The demo app in <code>apps/demo-solid</code> runs on Linux with <code>npm run start-linux</code>. Its WebSpec page compares the layout of 441 fixtures with Chromium.</p>`,21)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
